-- SQL INSERT for case_studies: Trust, But Re-Execute
-- Generated from BLOG_SPOT_REPORTS.md by md2lexical.mjs
-- NOTE: id omitted (sequence assigns); experience resolved by subquery; verify tag names exist in prod.

INSERT INTO "case_studies" (
    "title",
    "experience_id",
    "summary",
    "content",
    "slug",
    "published_at",
    "featured",
    "updated_at",
    "created_at",
    "meta_title",
    "meta_description"
) VALUES (
    'Trust, But Re-Execute',
    (SELECT id FROM "experiences" WHERE "title" ILIKE '%seekout%' LIMIT 1),
    '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"An agent that writes analytics reports will eventually invent a statistic. Ours announced a 26.7% reply rate no query produced. This is how Spot''s report generation was rebuilt so a report cannot state a number it didn''t compute — and the blind, adversarial scoreboard that proves it.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0}],"direction":"ltr"}}',
    '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"tag":"h1","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The Context","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Spot is SeekOut''s agentic AI recruiter. One of the things it does is write analytics reports: a hiring manager asks \"how is the senior pipeline actually looking,\" a multi-turn agent probes forty-odd hiring tables, decides what story the data tells, and lays the answer out as an editorial brief — KPI strips, funnels, quote cards, prose that reads like an analyst wrote it.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The hard part isn''t making a model write. Models love to write. The hard part is that an analytics report makes claims, and claims in a hiring report get acted on. Someone reads \"39 candidates presented\" and walks into a Monday meeting holding that number.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I''d spent weeks making these reports beautiful. Rebuilt the component library to one visual language. Made the charts stop lying — gauges that show the real value instead of capping it, ranked lists that keep their sort. Blind judges compared the rebuilt output head-to-head against the old build and preferred it 11 to 0. Presentation scores hit an all-time high.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The breaking point came when I ran fact verification against that golden battery for the first time. Sixteen defects a reader would act on and three invented figures, sitting under the best-looking reports we''d ever produced. The flagship example was a cover tile announcing a ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"26.7% candidate reply rate","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" that no query anywhere in the system produced. The model wanted a strong close for its recommendation section, so it manufactured one.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"We had been optimizing how reports looked, with a scoreboard that could not see whether they were true.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"horizontalrule","version":1},{"tag":"h1","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The Problem","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Call it scoreboard blindness. Every evaluation we had — aesthetic judges, layout scores, edit-success rates — measured polish, and polish and truth turn out to be fully independent variables. Underneath the pretty pages, four failure modes were compounding:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"tag":"ul","type":"list","start":1,"format":"","indent":0,"version":1,"children":[{"type":"listitem","value":1,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Confident invention","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":": prose stating figures no query produced. The 26.7% tile is the poster child, but \"24 of 36 candidates contacted\" with zero backing SQL is the same disease in a quieter outfit.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":2,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Wrong-column funnels","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":": a pipeline funnel counting stages off ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"campaign_candidates.status","type":"text","style":"","detail":0,"format":16,"version":1},{"mode":"normal","text":" — a column the schema explicitly forbids for stage counting — producing \"5 presented\" directly beneath a cover tile saying 39 were presented. Both numbers rendered beautifully.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":3,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Cross-panel contradiction","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":": the same metric appearing in two panels with two different values, because each panel''s query made its own choices and nothing ever compared them.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":4,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The eyeball ceiling","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":": a single report carries a dozen panels of SQL. Nobody reviews ninety panels of SQL by hand, and the one person who tries stops being able to see anything else.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr","listType":"bullet"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"None of this is a prompt problem you can nag your way out of. A prompt is a suggestion. The model had plenty of suggestions already.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"horizontalrule","version":1},{"tag":"h1","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The Solution","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The whole rebuild rests on one split: ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"taste lives in the prompts, the meaning of each column lives with the data, and correctness lives in code.","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" Column semantics — what ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"presented","type":"text","style":"","detail":0,"format":16,"version":1},{"mode":"normal","text":" actually counts, which tables may define a funnel stage — moved out of prose instructions and into ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"__dashboard_meta__","type":"text","style":"","detail":0,"format":16,"version":1},{"mode":"normal","text":" schema metadata, the single counting authority for author and judge alike. No sweeping data rules in the prompts. No aesthetic opinions in the lints.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"tag":"h3","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Explore-First Authoring: No Data Pack, No Excuses","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The old pipeline handed the author a pre-built data pack and a ~7,000-token schema registry dumped into its prompt. It trusted the handoff, and the handoff was always slightly wrong. The rebuilt author gets nothing. It discovers the schema itself through three tools — ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"list_tables","type":"text","style":"","detail":0,"format":16,"version":1},{"mode":"normal","text":", ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"preview_table","type":"text","style":"","detail":0,"format":16,"version":1},{"mode":"normal","text":", ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"run_query","type":"text","style":"","detail":0,"format":16,"version":1},{"mode":"normal","text":" — writes every query it intends to show, and emits the whole report in one pass.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"One detail here turned out to be load-bearing: the turn budget. The SDK default of 10 tool turns was silently killing 2 of 14 generations before they could finish exploring. The fix is a config field, not a heroic one:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"quote","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"# common/config.py (trimmed)\nviews_max_turns: int = Field(default=25, ge=5, le=100)\n# A turn ceiling is an infrastructure circuit breaker, not pacing.\n# Size it for the biggest honest workload, then treat hitting it as a bug.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The observation that generalizes: agents don''t fail loudly at their turn ceiling — they fail ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"politely","type":"text","style":"","detail":0,"format":2,"version":1},{"mode":"normal","text":", emitting whatever half-finished thing they have. If you didn''t size the budget deliberately, your ceiling is choosing your quality for you.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"tag":"h3","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Server Grounding: The Page Shows What the Database Returned","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Every panel''s SQL is re-executed server-side, read-only, through a static-analysis stack that parses each query once and walks the AST with rule objects: table allowlists, column existence, tenant scoping, double-count detection. The interesting rule is the one that killed the wrong-column funnels — it follows aliases, so renaming the forbidden column inside a CTE doesn''t launder it:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"quote","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"# domains/dashboards/sql_lint.py (trimmed)\nclass StatusFunnelRule(Rule):\n    \"\"\"Funnel stages may not be counted off campaign_candidates.status —\n    the schema defines exclusive per-stage formulas. Alias-aware: a stage\n    cohort built off a renamed CTE column is still caught.\"\"\"\n    def visit_column(self, node: exp.Column, ctx: LintContext) -> None:\n        origin = ctx.resolve_origin(node)   # walks CTE aliases back to the base column\n        if origin == (\"campaign_candidates\", \"status\") and ctx.in_stage_aggregation(node):\n            ctx.violation(node, \"funnel stage counted off forbidden column\")","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Taint-tracking through ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"WITH","type":"text","style":"","detail":0,"format":16,"version":1},{"mode":"normal","text":" clauses sounds exotic; with a real SQL parser it''s an afternoon, and it converts a prompt guideline the model kept \"creatively interpreting\" into a wall it physically cannot pass. A failing panel gets one mechanical repair attempt from the machine-readable violation, then it''s dropped.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"tag":"h3","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"A Judge That Cannot Type","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The last pass is an LLM judge with one constraint that does all the work: ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"it has no tool that accepts a number it typed itself.","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" Every value it can emit flows from a pure function reading freshly queried rows.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"quote","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"# the judge''s entire action space (trimmed)\nJUDGE_TOOLS = [\n    check_all_numbers,         # every prose figure vs fresh rows — unit-aware\n    lint_all_sql,              # every panel back through the full lint set\n    cross_panel_conflicts,     # same-label metrics that disagree across panels\n    run_query,\n    repair_sql,                # repaired SQL is re-executed and re-linted\n    fix_or_drop_prose_number,  # rebind a figure to its cell, or delete the sentence cleanly\n    drop_panel,\n]","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This is capability design instead of instruction design. You can tell a model \"never invent figures\" and it will agree enthusiastically while doing it anyway; remove the affordance and the failure mode stops existing. The bulk sweeps matter too — ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"check_all_numbers","type":"text","style":"","detail":0,"format":16,"version":1},{"mode":"normal","text":" is unit-aware, so a fabricated \"26.7%\" can no longer confirm itself against some unrelated bare count that happens to contain a 26.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"tag":"h3","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Fail Closed: Silence Is Failure","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This rule was paid for, not designed. An early version of the fact-checker was hitting ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"MaxTurnsExceeded","type":"text","style":"","detail":0,"format":16,"version":1},{"mode":"normal","text":" on large reports, the exception was swallowed, and the log sanitizer stripped ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"exc_info","type":"text","style":"","detail":0,"format":16,"version":1},{"mode":"normal","text":" — so 6 of 14 reports were shipping unjudged while the dashboard said everything was fine:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"quote","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"# before: a dead judge was indistinguishable from a passing one\nexcept MaxTurnsExceeded:\n    logger.warning(\"judge did not finish\")   # exc_info stripped upstream\n    verdict = None                           # fail open — report ships unjudged\n\n# after: silence is failure\nif verdict is None or not verdict.completed:\n    raise GenerationFailed(\"unjudged reports do not ship\")","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"We found it because a score moved the wrong way after a fix — the measurement loop caught its own instrument failing, which is the only reason to trust the loop at all. Fail-open evaluation is worse than no evaluation: it produces confidence instead of information. The companion rule is the drop floor — if more than a third of a report''s panels are dropped, no artifact ships. A report that''s mostly holes is not a report.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"tag":"h3","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Streaming the Skeleton: Perceived Latency Is the Latency","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Correct and slow is still a bad product. A grounded, judged generation runs about 220 seconds end to end, and no amount of optimism makes a hiring manager enjoy a 3-minute spinner. So the pipeline streams: a mid-loop checkpoint emits the plan the moment the author commits to one, then panels land as they ground.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"quote","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"// the stream reducer (trimmed) — SSE events over the chat channel\ncase \"report_plan\":   draft.outline = event.plan; break;             // first paint\ncase \"report_panel\":  draft.panels[event.key] = event.panel; break;  // last-wins by key\ncase \"report_final\":  return event.report;                           // grounded + judged\n// idle heartbeats re-emit the freshest phase every 15s,\n// and replayed events flow through this same reducer — resume === live","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Two decisions earn their keep here. Last-wins keyed events mean a reconnecting client can replay the persisted event log through the exact reducer the live stream uses — reload-resume isn''t a second code path, it''s the same one. And streaming the ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"outline","type":"text","style":"","detail":0,"format":2,"version":1},{"mode":"normal","text":" first cut time-to-first-view from ~125 seconds to ~47 without changing what ships: the rigor is unchanged, the spinner just stopped hogging the stage.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"tag":"h3","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"What I considered and rejected","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"tag":"ul","type":"list","start":1,"format":"","indent":0,"version":1,"children":[{"type":"listitem","value":1,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Better prompts.","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" About 250 lines of hardcoded data doctrine — canonical funnel definitions, per-rate SQL formulas — already lived in the prompts, and the model was penalized for obeying them. All of it came out. Prompts keep the taste; walls keep the rules.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":2,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Keeping the pre-generation data pack.","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" No. An author handed a digest trusts the digest. Making it look at the real tables is slower and correct, in that order.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":3,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Letting the judge free-write corrections.","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" No. A judge that can type a number is just a second author with better branding.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":4,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Wholesale regeneration on every edit.","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" No. In a study of 139 isolated edits, the rebuild-everything path caused 7 of the 8 damaging incidents in the corpus. Edits became narrow typed operations — a rename runs no queries, a filter change re-runs one panel, table shaping goes through deterministic ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"sqlglot","type":"text","style":"","detail":0,"format":16,"version":1},{"mode":"normal","text":" mutations like ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"set_order_by","type":"text","style":"","detail":0,"format":16,"version":1},{"mode":"normal","text":" — and the regression rate fell to 1 in 45.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr","listType":"bullet"},{"type":"horizontalrule","version":1},{"tag":"h1","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The Impact","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The scoreboard behind these numbers: a fixed 15-prompt battery on seeded data, judges pinned and blind (they never see what changed, so a score delta is a code delta), every panel''s SQL re-executed rather than eyeballed, and one strict rule — a single wrong number a reader would act on caps that report at 1 out of 5. It''s a bench, not a benchmark; the honest claim is direction and consistency, not decimals.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"tag":"ul","type":"list","start":1,"format":"","indent":0,"version":1,"children":[{"type":"listitem","value":1,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Invented figures went from 3 per audit run to 0.","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" The unit-aware sweep is why: a fabricated percentage no longer has anything it can accidentally match.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":2,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Reader-impacting defects dropped 94%","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" — 18 to 1 — across five audit runs in about thirty hours. The last run checked 56 panels and found none wrong.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":3,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The wrong-column funnels went from a fact score of 1 to a clean 5","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" on both report types that had them, once column meaning moved out of prompts and into schema metadata. Same model, same asks; the only thing that changed is where the truth lives.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":4,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Time-to-first-view fell ~62%","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" (about 125s to 47s) from streaming the outline — a perceived-latency win that cost nothing in rigor.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":5,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"What I''m especially proud of is the ratchet: every real defect the battery finds becomes a permanent regression test. The scoreboard only gets meaner, and it has already caught one of its own judges dying.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr","listType":"bullet"},{"type":"horizontalrule","version":1},{"tag":"h1","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"What It Cost","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The honest column. Full generation still runs about 220 seconds — exploration, grounding, and a three-sweep judge pass all cost real time, and streaming changes how the wait feels, not how long the work takes. A fail-closed pipeline sometimes ships nothing: an ungroundable ask produces no report, which is correct and still a conversation you have to have with users. And the first re-architecture attempt scored ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"worse","type":"text","style":"","detail":0,"format":2,"version":1},{"mode":"normal","text":" than the baseline it replaced — that was the silent judge death, and it was a humbling week. The measurement loop exists precisely for the weeks like that one.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"horizontalrule","version":1},{"tag":"h1","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Closing","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The rule is simple and load-bearing: ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"no model is ever the source of truth — every number a report shows is one the database returned.","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" The model''s job is the story. The database''s job is the numbers.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Somewhere in the audit archive there''s still that handsome July report with its invented 26.7%. I keep it around. It''s the best argument the pipeline ever made for itself.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0}],"direction":"ltr"}}',
    'seekout-spot-trust-but-re-execute',
    '2026-08-24T09:03:45.383Z',
    false,
    '2026-08-24T09:03:45.383Z',
    '2026-08-24T09:03:45.383Z',
    'Trust, But Re-Execute — Fact-Checked AI Report Generation',
    'How SeekOut Spot''s agentic report generation was rebuilt to be correct by construction: explore-first authoring, server-side SQL re-execution, a judge that cannot type numbers, and a blind audit battery that cut reader-impacting defects 94%.'
);

